<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Portal Siswa — SIGAP</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@600&family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@600;700&display=swap');
        :root { --pine:#153f37; --ink:#182421; --soft:#4b5b56; --paper:#f1f4f2; --line:#d9e1dc; --amber:#c9821e; }
        * { box-sizing:border-box; } body { margin:0; padding:44px; background:var(--paper); color:var(--ink); font-family:Inter,sans-serif; }
        .page { max-width:1472px; margin:auto; } .top { display:flex; justify-content:space-between; gap:24px; align-items:flex-start; } .eyebrow { color:var(--amber); font:600 16px 'IBM Plex Mono',monospace; letter-spacing:.08em; } h1 { margin:6px 0 6px; font:700 34px/1.15 'Space Grotesk',sans-serif; letter-spacing:-.03em; } .lead { margin:0 0 32px; font-size:18px; color:var(--soft); }
        .card { overflow:hidden; margin-bottom:32px; border:1px solid var(--line); border-radius:22px; background:#fff; box-shadow:0 8px 24px rgba(21,63,55,.07); } .card-title { padding:24px 30px; border-bottom:1px solid var(--line); font:700 21px 'Space Grotesk',sans-serif; } .card-body { padding:28px 30px 26px; }
        .grid { display:grid; grid-template-columns:1fr 1fr; gap:18px; } .field { margin-bottom:22px; } label { display:block; margin-bottom:9px; color:var(--soft); font-weight:600; } input, select { width:100%; height:63px; padding:0 24px; border:2px solid var(--line); border-radius:15px; background:#fff; color:var(--ink); font:20px Inter,sans-serif; } input:focus,select:focus { outline:0; border-color:var(--pine); } input[readonly] { background:#f7f9f8; color:var(--soft); }
        button { border:0; border-radius:14px; padding:17px 30px; background:var(--pine); color:#fff; cursor:pointer; font:700 18px Inter,sans-serif; } button:hover { background:#1e5a4d; } .hint { margin:13px 0 0; padding:16px 18px; border-radius:12px; background:var(--paper); color:var(--soft); font-size:16px; }
        .alert { margin:0 0 22px; padding:14px 17px; border-radius:12px; color:#8d3c2a; background:#fdf3f1; } .success { color:#176344; background:#e5f4ec; } table { width:100%; border-collapse:collapse; } th { padding:16px 30px; background:var(--paper); color:var(--soft); text-align:left; font-size:14px; letter-spacing:.05em; text-transform:uppercase; } td { padding:20px 30px; border-top:1px solid var(--line); font-size:17px; } .time { font:600 17px 'IBM Plex Mono',monospace; } .badge { display:inline-flex; align-items:center; gap:8px; padding:9px 14px; border-radius:999px; font:600 14px 'IBM Plex Mono',monospace; } .badge::before { content:'●'; } .pending { color:#9a660d; background:#fff0cf; } .approved { color:#147356; background:#dff4eb; } .rejected { color:#a33d2c; background:#fbe4df; } .empty { padding:34px 30px; color:var(--soft); text-align:center; }
        .profile { display:flex; align-items:center; gap:12px; padding:8px 0; } .avatar { width:54px; height:54px; display:grid; place-items:center; overflow:hidden; border:3px solid #fff; border-radius:50%; background:#dcece5; color:var(--pine); box-shadow:0 3px 10px rgba(21,63,55,.18); font:700 18px 'Space Grotesk',sans-serif; } .avatar img { width:100%; height:100%; object-fit:cover; } .profile-name { font-weight:700; } .profile-role { margin-top:3px; color:var(--soft); font-size:13px; } .logout,.edit-profile { margin-top:8px; background:transparent; border:1px solid var(--line); color:var(--soft); padding:10px 16px; font-size:14px; } .edit-profile { cursor:pointer; } .profile-form { margin:-12px 0 28px; padding:22px; border:1px solid var(--line); border-radius:16px; background:#fff; } .profile-form summary { cursor:pointer; color:var(--pine); font-weight:700; } .profile-form form { margin-top:20px; } .profile-form button { font-size:15px; padding:13px 20px; } @media (max-width:700px) { body { padding:25px 16px; } .top { gap:12px; } .profile-name,.profile-role { display:none; } h1 { font-size:29px; } .grid { grid-template-columns:1fr; gap:0; } .card-title,.card-body { padding-left:20px; padding-right:20px; } th,td { padding-left:16px; padding-right:16px; } th:nth-child(2),td:nth-child(2) { display:none; } }
    </style>
</head>
<body><main class="page">
    <div class="top"><div><div class="eyebrow">PORTAL SISWA</div><h1>Ajukan & pantau izin keluar</h1><p class="lead">Izin harus disetujui guru piket sebelum kamu boleh keluar gerbang.</p></div><div class="profile"><div class="avatar" id="avatar-preview">@if($siswa?->foto_profil_path)<img src="{{ asset('storage/' . $siswa->foto_profil_path) }}" alt="Foto profil {{ auth()->user()->name }}">@else{{ strtoupper(substr(auth()->user()->name, 0, 1)) }}@endif</div><div><div class="profile-name">{{ auth()->user()->name }}</div><div class="profile-role">{{ $siswa?->kelas ?? 'Siswa' }}</div></div><form method="POST" action="{{ route('logout') }}">@csrf<button class="logout" type="submit">Keluar</button></form></div></div>
    <details class="profile-form" @if($errors->has('name') || $errors->has('email') || $errors->has('foto_profil')) open @endif><summary>Edit profil</summary><form method="POST" action="{{ route('user.profile.update') }}" enctype="multipart/form-data">@csrf @method('PATCH')<div class="grid"><div class="field"><label for="profile_name">Nama</label><input id="profile_name" name="name" value="{{ old('name', auth()->user()->name) }}" required></div><div class="field"><label for="profile_email">Email</label><input type="email" id="profile_email" name="email" value="{{ old('email', auth()->user()->email) }}" required></div><div class="field"><label for="profile_kelas">Kelas</label><input id="profile_kelas" name="kelas" value="{{ old('kelas', $siswa?->kelas) }}" required></div><div class="field"><label for="foto_profil">Foto profil (opsional)</label><input type="file" id="foto_profil" name="foto_profil" accept="image/png,image/jpeg,image/webp"></div></div><button type="submit">Simpan profil</button></form></details>
    <section class="card"><div class="card-title">Form pengajuan izin keluar</div><div class="card-body">
        @if(session('success'))<div class="alert success">{{ session('success') }}</div>@endif
        @if($errors->any())<div class="alert">{{ $errors->first() }}</div>@endif
        <form method="POST" action="{{ route('user.izin.store') }}" enctype="multipart/form-data">@csrf
            <div class="grid"><div class="field"><label for="kelas">Kelas</label><input id="kelas" name="kelas" value="{{ old('kelas', $siswa?->kelas) }}" {{ $siswa ? 'readonly' : '' }} required placeholder="Contoh: XI RPL 2"></div><div class="field"><label for="jam_keluar_rencana">Jam keluar rencana</label><input type="time" id="jam_keluar_rencana" name="jam_keluar_rencana" value="{{ old('jam_keluar_rencana') }}" required></div></div>
            <div class="field"><label for="alasan">Alasan</label><select id="alasan" name="alasan" required><option value="" disabled {{ old('alasan') ? '' : 'selected' }}>Pilih alasan izin</option>@foreach(['Dijemput orang tua','Keperluan keluarga','Berobat','Lainnya'] as $alasan)<option value="{{ $alasan }}" @selected(old('alasan') === $alasan)>{{ $alasan }}</option>@endforeach</select></div>
            <div class="field" id="deskripsi-wrap" style="display:{{ old('alasan') === 'Lainnya' ? 'block' : 'none' }}"><label for="deskripsi">Jelaskan alasan izin</label><input id="deskripsi" name="deskripsi" value="{{ old('deskripsi') }}" maxlength="500" placeholder="Tuliskan alasan izin secara singkat dan jelas"><p class="hint">Wajib diisi jika memilih alasan “Lainnya”.</p></div>
            <div class="field"><label for="bukti">Foto atau video bukti izin</label><input type="file" id="bukti" name="bukti" accept="image/png,image/jpeg,image/webp,video/mp4,video/quicktime,video/webm" required><p class="hint">Wajib diisi. Foto atau video MP4, MOV, WEBM (maks. 20 MB).</p></div>
            <button type="submit">Ajukan izin</button><p class="hint">Pengajuan akan masuk ke antrean guru piket. Kamu bisa pantau statusnya di riwayat bawah ini.</p>
        </form>
    </div></section>
    <section class="card"><div class="card-title">Riwayat izin saya</div>
        @if($izinKeluar->isEmpty())<div class="empty">Belum ada pengajuan izin keluar.</div>@else <table><thead><tr><th>Alasan</th><th>Kelas</th><th>Jam keluar</th><th>Status</th></tr></thead><tbody>@foreach($izinKeluar as $izin)<tr><td>{{ $izin->alasan }}</td><td>{{ $siswa->kelas }}</td><td class="time">{{ $izin->jam_keluar_rencana?->format('H:i') ?? $izin->jam_keluar_rencana }}</td><td><span class="badge {{ $izin->status }}">{{ ['pending' => 'Menunggu', 'approved' => 'Disetujui', 'rejected' => 'Ditolak'][$izin->status] }}</span></td></tr>@endforeach</tbody></table>@endif
    </section>
</main><script>const alasan = document.getElementById('alasan'); const deskripsiWrap = document.getElementById('deskripsi-wrap'); const deskripsi = document.getElementById('deskripsi'); function toggleDeskripsi() { const lainnya = alasan.value === 'Lainnya'; deskripsiWrap.style.display = lainnya ? 'block' : 'none'; deskripsi.required = lainnya; if (!lainnya) deskripsi.value = ''; } alasan.addEventListener('change', toggleDeskripsi); toggleDeskripsi();</script></body></html>
